        "text": "Bu hastada yağlı öğün sonrası başlayan ancak saatler içinde düzelmeyen sağ üst kadran ağrısına ateş, lökositoz/CRP yüksekliği, pozitif Murphy bulgusu ve USG’de taşla birlikte duvar kalınlaşması-perikolesistik sıvı eşlik etmektedir. Bu kombinasyon geçici sistik kanal obstrüksiyonundan ibaret biliyer kolikten ziyade akut taşlı kolesistiti destekler; belirgin kolestaz, koledok dilatasyonu veya lipaz yüksekliği olmaması kolanjit, koledok taşı ve pankreatiti geri plana iter."
