        "text": "Tarama mamografisinde saptanan sol meme lezyonu nedeniyle ileri değerlendirmeye alınmıştır; hasta meme başı akıntısı, cilt kızarıklığı veya hızlı büyüyen kitle fark etmemiştir. Ailesinde erken yaşta meme ya da over kanseri öyküsü yoktur. Aksillada elle fark ettiği şişlik, kol ödemi veya ağrı tariflemiyor. Daha önce meme veya aksilla cerrahisi geçirmemiş ve neoadjuvan tedavi almamıştır. Görüntüleme sonrası yapılan kor biyopsi invaziv duktal karsinom ile uyumlu bulunmuştur."
